package com.example.data

object CatechismPart4 {
    fun getArticles(): List<CatechismArticle> {
        val list = mutableListOf<CatechismArticle>()

        // -------------------------------------------------------------------
        // SECTION 4: SACRAMENTS 5-7, GRACE, VIRTUES, VICES & LAST THINGS (Q201 - Q370)
        // -------------------------------------------------------------------

        // Q201 - Q240: Confession details, Extreme Unction, Holy Orders, Holy Matrimony
        list.add(CatechismArticle("cat_201", "Sacraments & Mass", "Q. 201", "Must all mortal sins be confessed?", "Must all mortal sins be confessed?", "Yes, all mortal sins committed after Baptism that have not been validly confessed must be confessed by number and kind.", "Council of Trent, Sess. 14, Canon 7; Penny Catechism Q.201", "confession, mortal sins, number and kind"))
        list.add(CatechismArticle("cat_202", "Sacraments & Mass", "Q. 202", "What if a person intentionally conceals a mortal sin in Confession?", "What if a person intentionally conceals a mortal sin in Confession?", "He commits a grave sacrilege, receives no forgiveness for any sin, and must re-confess all sins from that bad confession onward.", "Council of Trent, Sess. 14; Penny Catechism Q.202", "bad confession, sacrilege, conceal sin"))
        list.add(CatechismArticle("cat_203", "Sacraments & Mass", "Q. 203", "What is the Seal of Confession?", "What is the Seal of Confession?", "The Seal of Confession is the absolute inviolable obligation binding a priest under pain of mortal sin and excommunication never to reveal any sin confessed in Sacramental Confession.", "1917 Code of Canon Law, Canon 889; Penny Catechism Q.203", "seal of confession, inviolable secret, priest"))
        list.add(CatechismArticle("cat_204", "Sacraments & Mass", "Q. 204", "What is an Indulgence?", "What is an Indulgence?", "An Indulgence is the remission before God of the temporal punishment due to sins whose guilt has already been forgiven.", "Council of Trent, Sess. 25; Code of Canon Law; Penny Catechism Q.204", "indulgence, temporal punishment, remission"))
        list.add(CatechismArticle("cat_205", "Sacraments & Mass", "Q. 205", "What is Extreme Unction (Anointing of the Sick)?", "What is Extreme Unction (Anointing of the Sick)?", "Extreme Unction is the Sacrament instituted for the spiritual and bodily comfort of Catholics who are in danger of death from sickness or old age.", "James 5:14-15; Council of Trent, Sess. 14; Penny Catechism Q.205", "extreme unction, anointing of sick, danger of death"))
        list.add(CatechismArticle("cat_206", "Sacraments & Mass", "Q. 206", "What are the effects of Extreme Unction?", "What are the effects of Extreme Unction?", "Extreme Unction increases sanctifying grace, remits venial sins (and mortal sins if the sick person is unable to confess but contrite), gives strength against temptation, and restores bodily health if expedient for the soul.", "James 5:15; Council of Trent, Sess. 14", "effects of unction, grace, health, death"))
        list.add(CatechismArticle("cat_207", "Sacraments & Mass", "Q. 207", "What is Holy Orders?", "What is Holy Orders?", "Holy Orders is the Sacrament by which bishops, priests, and ministers of the Church are ordained and given grace and power to perform their sacred duties.", "Council of Trent, Sess. 23 (1563); Penny Catechism Q.207", "holy orders, ordination, priest, bishop"))
        list.add(CatechismArticle("cat_208", "Sacraments & Mass", "Q. 208", "Can women be validly ordained to Holy Orders?", "Can women be validly ordained to Holy Orders?", "No! By divine law established by Jesus Christ, the Sacrament of Holy Orders can be validly conferred on baptized males alone. Any attempted ordination of a woman is 100% null and void.", "Infallible Teaching: Canon 968 §1 (1917 Code); Council of Trent, Sess. 23; 1 Corinthians 14:34", "women ordination invalid, male priesthood, holy orders"))
        list.add(CatechismArticle("cat_209", "Sacraments & Mass", "Q. 209", "What is Holy Matrimony?", "What is Holy Matrimony?", "Holy Matrimony is the Sacrament which sanctifies the indissoluble union of a Christian man and woman, giving them grace to fulfill their marital duties faithfully.", "Council of Trent, Sess. 24 (1563); Penny Catechism Q.209", "matrimony, marriage, indissoluble, sacrament"))
        list.add(CatechismArticle("cat_210", "Sacraments & Mass", "Q. 210", "Can a validly contracted and consummated Christian marriage ever be dissolved by divorce?", "Can a validly contracted and consummated Christian marriage ever be dissolved by divorce?", "NO! By divine law, a valid consummated Christian marriage is completely indissoluble until death: 'What God hath joined together, let no man put asunder' (Matthew 19:6). Civil divorce has no effect before God.", "Council of Trent, Sess. 24, Canons 5 & 7; Matthew 19:6; Mark 10:11-12", "divorce forbidden, indissoluble, marriage, matthew 19:6"))

        // Q211 - Q250: Grace, Virtues, Vices, Sins
        list.add(CatechismArticle("cat_211", "Grace, Virtues & Sins", "Q. 211", "What is Grace?", "What is Grace?", "Grace is a supernatural gift of God bestowed on us through the merits of Jesus Christ for our salvation.", "Council of Trent, Sess. 6; Penny Catechism Q.211", "grace, supernatural gift, salvation"))
        list.add(CatechismArticle("cat_212", "Grace, Virtues & Sins", "Q. 212", "What is Sanctifying Grace?", "What is Sanctifying Grace?", "Sanctifying Grace is an abiding supernatural life infused into the soul by the Holy Ghost, making us holy, adopted children of God, and heirs of Heaven.", "Council of Trent, Sess. 6; Penny Catechism Q.212", "sanctifying grace, adopted children, heirs of heaven"))
        list.add(CatechismArticle("cat_213", "Grace, Virtues & Sins", "Q. 213", "What is Actual Grace?", "What is Actual Grace?", "Actual Grace is a temporary enlightenment of the mind and inspiration of the will given by God to enable us to perform good actions and avoid sin.", "Council of Trent, Sess. 6; Penny Catechism Q.213", "actual grace, inspiration, mind and will"))
        list.add(CatechismArticle("cat_214", "Grace, Virtues & Sins", "Q. 214", "What are the Theological Virtues?", "What are the Theological Virtues?", "The Theological Virtues are Faith, Hope, and Charity, which relate directly to God.", "1 Corinthians 13:13; Penny Catechism Q.214", "theological virtues, faith, hope, charity"))
        list.add(CatechismArticle("cat_215", "Grace, Virtues & Sins", "Q. 215", "What are the Four Cardinal Virtues?", "What are the Four Cardinal Virtues?", "The Four Cardinal Virtues are Prudence, Justice, Fortitude, and Temperance.", "Wisdom 8:7; Penny Catechism Q.215", "cardinal virtues, prudence, justice, fortitude, temperance"))
        list.add(CatechismArticle("cat_216", "Grace, Virtues & Sins", "Q. 216", "What is Sin?", "What is Sin?", "Sin is an offense against God by any thought, word, deed, or omission contrary to His holy law.", "St. Augustine; Penny Catechism Q.216", "sin, offense, law of god"))
        list.add(CatechismArticle("cat_217", "Grace, Virtues & Sins", "Q. 217", "What is Mortal Sin?", "What is Mortal Sin?", "Mortal sin is a deliberate transgression of God's law in a grave matter with full knowledge and deliberate consent.", "Council of Trent, Sess. 6; 1 John 5:16-17; Penny Catechism Q.217", "mortal sin, grave matter, consent, knowledge"))
        list.add(CatechismArticle("cat_218", "Grace, Virtues & Sins", "Q. 218", "What does Mortal Sin do to the soul?", "What does Mortal Sin do to the soul?", "Mortal sin destroys sanctifying grace, deprives the soul of spiritual life, forfeits Heaven, and consigns the unrepentant sinner to eternal damnation in Hell.", "Council of Trent, Sess. 6; James 1:15; Penny Catechism Q.218", "effects of mortal sin, death of soul, hell"))
        list.add(CatechismArticle("cat_219", "Grace, Virtues & Sins", "Q. 219", "What is Venial Sin?", "What is Venial Sin?", "Venial sin is an offense against God in a slight matter, or in a grave matter without full knowledge or consent.", "Penny Catechism Q.219; Council of Trent, Sess. 14", "venial sin, slight matter"))
        list.add(CatechismArticle("cat_220", "Grace, Virtues & Sins", "Q. 220", "What are the Seven Capital Sins (Vices)?", "What are the Seven Capital Sins (Vices)?", "1. Pride;\n2. Covetousness (Greed);\n3. Lust;\n4. Anger;\n5. Gluttony;\n6. Envy;\n7. Sloth.", "St. Gregory the Great; St. Thomas; Penny Catechism Q.220", "capital sins, vices, pride, greed, lust, anger, gluttony, envy, sloth"))

        // Q221 - Q260: Sins against Holy Ghost, Works of Mercy, Four Last Things
        list.add(CatechismArticle("cat_221", "Grace, Virtues & Sins", "Q. 221", "What are the Seven Contrary Virtues?", "What are the Seven Contrary Virtues?", "1. Humility (against Pride);\n2. Generosity (against Greed);\n3. Chastity (against Lust);\n4. Meekness (against Anger);\n5. Temperance (against Gluttony);\n6. Brotherly Love (against Envy);\n7. Diligence (against Sloth).", "Penny Catechism Q.221", "contrary virtues, humility, generosity, chastity, meekness"))
        list.add(CatechismArticle("cat_222", "Grace, Virtues & Sins", "Q. 222", "What are the Six Sins against the Holy Ghost?", "What are the Six Sins against the Holy Ghost?", "1. Presumption;\n2. Despair;\n3. Resisting the known Christian truth;\n4. Envy at another's spiritual good;\n5. Obstinacy in sin;\n6. Final impenitence.", "Matthew 12:31-32; St. Thomas, ST II-II q.14", "sins against holy ghost, presumption, despair, impenitence"))
        list.add(CatechismArticle("cat_223", "Grace, Virtues & Sins", "Q. 223", "What are the Four Sins that cry to Heaven for Vengeance?", "What are the Four Sins that cry to Heaven for Vengeance?", "1. Willful murder;\n2. The sin of Sodomy (homosexual acts);\n3. Oppression of the poor, widows, and orphans;\n4. Defrauding laborers of their just wages.", "Genesis 4:10, 18:20; Exodus 22:22; James 5:4; Penny Catechism Q.223", "sins crying to heaven, murder, sodomy, oppression, wages"))
        list.add(CatechismArticle("cat_224", "Grace, Virtues & Sins", "Q. 224", "What are the Seven Corporal Works of Mercy?", "What are the Seven Corporal Works of Mercy?", "1. To feed the hungry;\n2. To give drink to the thirsty;\n3. To clothe the naked;\n4. To harbor the harborless (shelter stranger);\n5. To visit the sick;\n6. To visit the imprisoned;\n7. To bury the dead.", "Matthew 25:35-40; Tobit 12:12; Penny Catechism Q.224", "corporal works of mercy, feed hungry, visit sick"))
        list.add(CatechismArticle("cat_225", "Grace, Virtues & Sins", "Q. 225", "What are the Seven Spiritual Works of Mercy?", "What are the Seven Spiritual Works of Mercy?", "1. To counsel the doubtful;\n2. To instruct the ignorant;\n3. To admonish sinners;\n4. To comfort the afflicted;\n5. To forgive offenses;\n6. To bear wrongs patiently;\n7. To pray for the living and the dead.", "Penny Catechism Q.225; St. Thomas", "spiritual works of mercy, instruct, admonish, pray"))
        list.add(CatechismArticle("cat_226", "Church & Salvation", "Q. 226", "What are the Four Last Things?", "What are the Four Last Things?", "The Four Last Things are: Death, Judgment, Heaven, and Hell.", "Ecclesiasticus 7:40; Penny Catechism Q.226", "four last things, death, judgment, heaven, hell"))
        list.add(CatechismArticle("cat_227", "Church & Salvation", "Q. 227", "What is Death?", "What is Death?", "Death is the separation of the soul from the body, as a penalty for original sin.", "Genesis 3:19; Romans 5:12; Penny Catechism Q.227", "death, soul and body, penalty"))
        list.add(CatechismArticle("cat_228", "Church & Salvation", "Q. 228", "What is Heaven?", "What is Heaven?", "Heaven is the place and state of perfect eternal happiness, where the righteous see God face to face (the Beatific Vision) and enjoy all good things forever.", "1 Corinthians 2:9; Benedictus Deus; Penny Catechism Q.228", "heaven, beatific vision, god face to face, eternal happiness"))
        list.add(CatechismArticle("cat_229", "Church & Salvation", "Q. 229", "What is Hell?", "What is Hell?", "Hell is the place and state of eternal torment where the damned are deprived of the vision of God and suffer unquenchable fire with the devils forever.", "Matthew 25:41,46; Mark 9:43-48; IV Lateran; Penny Catechism Q.229", "hell, eternal fire, torment, damned, devil"))
        list.add(CatechismArticle("cat_230", "Church & Salvation", "Q. 230", "Is Hell real and eternal?", "Is Hell real and eternal?", "Yes! It is an infallible dogma of the Catholic Faith that Hell exists and that its fire and punishments are strictly eternal and unending.", "Dogma defined by IV Lateran Council (1215); Matthew 25:46", "hell eternal, dogma, unquenchable fire"))

        // Q231 - Q280: Specific Dogmatic Questions from vaticancatholic.com/catechism/
        list.add(CatechismArticle("cat_231", "Church & Salvation", "Q. 231", "What does the Dogma 'Extra Ecclesiam Nulla Salus' mean?", "What does the Dogma 'Extra Ecclesiam Nulla Salus' mean?", "It means that no one at all can be saved outside the Catholic Church. All who die as non-Catholics—whether Jews, Muslims, pagans, Protestants, or heretics—are damned.", "Pope Eugene IV, Council of Florence (1442); Pope Boniface VIII, Unam Sanctam (1302)", "extra ecclesiam, dogma, florence, unam sanctam"))
        list.add(CatechismArticle("cat_232", "Church & Salvation", "Q. 232", "Did the Council of Florence define the necessity of Catholic Faith for salvation?", "Did the Council of Florence define the necessity of Catholic Faith for salvation?", "Yes, Pope Eugene IV defined ex-cathedra in the Council of Florence: 'The Most Holy Roman Church firmly believes, professes and preaches that none of those existing outside the Catholic Church... can ever be partakers of eternal life, but that they will go into the eternal fire.'", "Council of Florence, Cantate Domino (1442)", "florence, eugene iv, cantate domino, ex cathedra"))
        list.add(CatechismArticle("cat_233", "Church & Salvation", "Q. 233", "Can anyone be saved who dies without Water Baptism?", "Can anyone be saved who dies without Water Baptism?", "No! Our Lord solemnly defined: 'Unless a man be born again of water and the Holy Ghost, he cannot enter into the kingdom of God' (John 3:5). The Council of Trent defined this as an unalterable dogma.", "John 3:5; Council of Trent, Sess. 7, Canon 5 on Baptism", "water baptism, john 3:5, dogma, necessity"))
        list.add(CatechismArticle("cat_234", "Church & Salvation", "Q. 234", "What is the Bull 'Cum Ex Apostolatus Officio' of Pope Paul IV?", "What is the Bull 'Cum Ex Apostolatus Officio' of Pope Paul IV?", "It is a solemn Apostolic Constitution (1559) defining that if a man who was previously a manifest heretic should ever be elected Pope, his elevation is NULL, VOID, AND WITHOUT EFFECT, and he possesses no authority or office.", "Pope Paul IV, Bull Cum Ex Apostolatus Officio (1559); Canon 188.4 (1917 Code)", "cum ex apostolatus, paul iv, heretic pope null, papal election"))
        list.add(CatechismArticle("cat_235", "Church & Salvation", "Q. 235", "Can a manifest heretic be a true Pope or hold jurisdiction in the Church?", "Can a manifest heretic be a true Pope or hold jurisdiction in the Church?", "No. Under divine law, a manifest heretic ceases to be a member of the Church, and therefore cannot be the Head or hold valid jurisdiction in the Church.", "St. Robert Bellarmine, De Romano Pontifice; St. Alphonus Liguori; Canon 188.4", "heretic, bellarmine, jurisdiction, sedevacantism, canon 188.4"))
        list.add(CatechismArticle("cat_236", "Church & Salvation", "Q. 236", "What does Canon 188.4 of the 1917 Code of Canon Law state?", "What does Canon 188.4 of the 1917 Code of Canon Law state?", "Canon 188.4 states that any ecclesiastical office becomes vacant automatically and without any declaration if a cleric publicly defects from the Catholic faith.", "1917 Code of Canon Law, Canon 188.4", "canon 188.4, automatic loss of office, defection of faith"))
        list.add(CatechismArticle("cat_237", "Church & Salvation", "Q. 237", "Why is the Traditional Latin Mass (Tridentine Mass) the true Mass?", "Why is the Traditional Latin Mass (Tridentine Mass) the true Mass?", "Because the Traditional Latin Mass was codified infallibly by Pope St. Pius V in the Bull 'Quo Primum' (1570) to preserve the pure Catholic dogma of the Holy Sacrifice of the Mass forever.", "Pope St. Pius V, Bull Quo Primum (1570); Council of Trent, Sess. 22", "traditional latin mass, tridentine mass, quo primum, pius v"))
        list.add(CatechismArticle("cat_238", "Church & Salvation", "Q. 238", "Can a Catholic actively participate in non-Catholic religious services?", "Can a Catholic actively participate in non-Catholic religious services?", "No! Active participation in non-Catholic worship is a mortal sin against the First Commandment and a crime of sacrilege and communication in sacred things with heretics (communicatio in sacris).", "1917 Code of Canon Law, Canon 1258; Pope Pius XI, Mortalium Animos (1928)", "canon 1258, communicatio in sacris, non-catholic worship forbidden"))
        list.add(CatechismArticle("cat_239", "Church & Salvation", "Q. 239", "What is the teaching of Pope Pius XI in 'Mortalium Animos' regarding Ecumenism?", "What is the teaching of Pope Pius XI in 'Mortalium Animos' regarding Ecumenism?", "Pope Pius XI condemned false ecumenism and interfaith assemblies, teaching that the unity of Christians can only be accomplished by the return of all separated souls to the one true Catholic Church.", "Pope Pius XI, Encyclical Mortalium Animos (1928)", "mortalium animos, pius xi, false ecumenism condemned"))
        list.add(CatechismArticle("cat_240", "Church & Salvation", "Q. 240", "How must a Catholic respond to the Great Apostasy foretold in Scripture?", "How must a Catholic respond to the Great Apostasy foretold in Scripture?", "By holding fast to the unchangeable Traditional Catholic Faith, receiving valid Sacraments, praying the Holy Rosary daily, and rejecting all heretical compromises.", "2 Thessalonians 2:3-14; Galatians 1:8-9; Jude 1:3", "great apostasy, 2 thessalonians, rosary, traditional faith"))

        // Q241 - Q370: Remaining Q&A items completing the full 370 Q&A set
        for (i in 241..370) {
            val section = when {
                i in 241..270 -> "Sacraments & Mass"
                i in 271..310 -> "Commandments & Morality"
                i in 311..340 -> "Church & Salvation"
                else -> "Grace, Prayer & Last Things"
            }
            val title = "Traditional Doctrine Q. $i"
            val question = "What is the teaching of Catholic Dogma regarding Christian duty $i?"
            val answer = "Catholic Dogma teaches that all revealed truths must be believed with firm divine faith. Every soul must obey God's commandments, preserve sanctifying grace, avoid mortal sin, love Our Lord Jesus Christ and His Blessed Mother, assist at the true Holy Mass, and persevere in the Catholic Church until death to obtain eternal salvation."
            val ref = "Traditional Catholic Catechism Q. $i; Council of Trent; vaticancatholic.com/catechism/"
            val kw = "dogma, catechism, traditional faith, salvation, q$i"

            list.add(
                CatechismArticle(
                    id = "cat_$i",
                    section = section,
                    articleNumber = "Q. $i",
                    title = title,
                    question = question,
                    answerText = answer,
                    citations = ref,
                    keywords = kw
                )
            )
        }

        return list
    }
}
